const req = $json;
const body = req.body ?? req;
const required = ['tenant_id','workflow_id','invocation_id','idempotency_key','schema_version'];
for (const key of required) {
  if (!body[key]) throw new Error(`Missing ${key}`);
}
if (!String(body.schema_version).startsWith('2.')) throw new Error('Unsupported Jahorin n8n schema');
return [{
  json: {
    ...body,
    received_at: new Date().toISOString(),
    phase: 'acting',
    input: body.input ?? {},
    memory_context: Array.isArray(body.memory_context) ? body.memory_context : [],
  }
}];

const input = $json.input ?? {};
const intent = String(input.intent ?? input.prompt ?? input.query ?? '').trim();
return [{
  json: {
    workflow_id: $json.workflow_id,
    status: 'completed',
    result: {
      phase: 'guided',
      intent,
      task_id: $json.task_id ?? null,
      next: input.next ?? null,
      message: input.guidance ?? 'Jahorin is guiding this task.',
    },
    evidence: [{
      kind: 'realtime_turn',
      source: 'n8n',
      at: new Date().toISOString(),
      invocation_id: $json.invocation_id,
    }],
    memory_candidates: [{
      persist: true,
      provenance: 'task_summary',
      kind: 'task_summary',
      scope: 'session',
      importance: 0.35,
      content: intent ? `Turn intent: ${intent}` : 'Realtime Jahorin turn completed.',
    }],
  }
}];
